  1	/**
  2	 * Unit tests for views/error-log.js — WP-006.
  3	 *
  4	 * Acceptance Criteria verified:
  5	 *   AC1  — SEVERITY_OPTIONS includes { value: 'audit', label: 'Audit' }.
  6	 *   AC2  — SEVERITY_OPTIONS includes { value: 'info', label: 'Info' }.
  7	 *   AC3  — The severity filter dropdown rendered by renderErrorLog contains
  8	 *           an "Audit" option and an "Info" option.
  9	 *
 10	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
 11	 * Run individually with:
 12	 *   node --test gui/public/js/views/error-log.test.mjs
 13	 */
 14	
 15	import { test } from 'node:test';
 16	import assert from 'node:assert/strict';
 17	import { JSDOM } from 'jsdom';
 18	
 19	// ---------------------------------------------------------------------------
 20	// jsdom setup — install globals before any module is imported
 21	// ---------------------------------------------------------------------------
 22	
 23	const dom = new JSDOM('<!DOCTYPE html><html><body><div id="toast-container"></div></body></html>', {
 24	    url: 'http://localhost/',
 25	});
 26	
 27	const { window } = dom;
 28	
 29	globalThis.document    = window.document;
 30	globalThis.window      = window;
 31	globalThis.location    = window.location;
 32	globalThis.HTMLElement = window.HTMLElement;
 33	globalThis.CSS = window.CSS ?? { escape: (s) => s.replace(/[!"#$%&'()*+,./:;<=>?@[\\\]^`{|}~]/g, '\\$&') };
 34	
 35	// ---------------------------------------------------------------------------
 36	// Minimal fetch mock (required by api.js)
 37	// ---------------------------------------------------------------------------
 38	
 39	globalThis.fetch = async () => ({
 40	    status: 200,
 41	    ok: true,
 42	    statusText: 'OK',
 43	    headers: { get: () => 'application/json' },
 44	    json: async () => ({ entries: [], total: 0, sources: [] }),
 45	});
 46	
 47	// ---------------------------------------------------------------------------
 48	// Import API and set up mocks
 49	// ---------------------------------------------------------------------------
 50	
 51	const { api } = await import('../api.js');
 52	
 53	api.errorLog = {
 54	    list:    async () => ({ entries: [], total: 0 }),
 55	    sources: async () => ({ sources: [] }),
 56	    clear:   async () => ({}),
 57	};
 58	
 59	// ---------------------------------------------------------------------------
 60	// Import module under test
 61	// ---------------------------------------------------------------------------
 62	
 63	const { renderErrorLog } = await import('./error-log.js');
 64	
 65	// ---------------------------------------------------------------------------
 66	// Helpers
 67	// ---------------------------------------------------------------------------
 68	
 69	/**
 70	 * Render the Error Log view into a fresh container and wait for async
 71	 * bootstrap (API fetch + DOM construction).
 72	 *
 73	 * @returns {Promise<HTMLElement>} The outermost container element.
 74	 */
 75	async function renderAndWait() {
 76	    const container = document.createElement('div');
 77	    container.id = 'app';
 78	    document.body.appendChild(container);
 79	
 80	    await renderErrorLog(container, {});
 81	
 82	    // Flush any remaining micro-tasks.
 83	    await new Promise((resolve) => setTimeout(resolve, 0));
 84	
 85	    return container;
 86	}
 87	
 88	/**
 89	 * Remove all rendered containers after each test.
 90	 */
 91	function cleanupContainers() {
 92	    document.body.querySelectorAll('#app').forEach((el) => el.remove());
 93	}
 94	
 95	// ---------------------------------------------------------------------------
 96	// Tests
 97	// ---------------------------------------------------------------------------
 98	
 99	test('AC1 — severity filter dropdown contains an "Audit" option', async () => {
100	    const container = await renderAndWait();

101	    try {
102	        const select = container.querySelector('#error-log-severity-filter');
103	        assert.ok(select, 'Severity filter <select> should exist');
104	
105	        const options = Array.from(select.querySelectorAll('option'));
106	        const auditOption = options.find((o) => o.value === 'audit');
107	        assert.ok(auditOption, 'Severity dropdown should have an option with value "audit"');
108	        assert.strictEqual(auditOption.textContent, 'Audit');
109	    } finally {
110	        cleanupContainers();
111	    }
112	});
113	
114	test('AC2 — severity filter dropdown contains an "Info" option', async () => {
115	    const container = await renderAndWait();
116	    try {
117	        const select = container.querySelector('#error-log-severity-filter');
118	        assert.ok(select, 'Severity filter <select> should exist');
119	
120	        const options = Array.from(select.querySelectorAll('option'));
121	        const infoOption = options.find((o) => o.value === 'info');
122	        assert.ok(infoOption, 'Severity dropdown should have an option with value "info"');
123	        assert.strictEqual(infoOption.textContent, 'Info');
124	    } finally {
125	        cleanupContainers();
126	    }
127	});
128	
129	test('AC3 — severity filter dropdown retains existing "Error" and "Warning" options', async () => {
130	    const container = await renderAndWait();
131	    try {
132	        const select = container.querySelector('#error-log-severity-filter');
133	        assert.ok(select, 'Severity filter <select> should exist');
134	
135	        const values = Array.from(select.querySelectorAll('option')).map((o) => o.value);
136	        assert.ok(values.includes('error'),   'Dropdown should still include "error"');
137	        assert.ok(values.includes('warning'), 'Dropdown should still include "warning"');
138	        assert.ok(values.includes('all'),     'Dropdown should still include "all"');
139	    } finally {
140	        cleanupContainers();
141	    }
142	});

